{
  "implementation": "import math
def solve(case):
    sentence_vectors = case["sentence_vectors"]
    query_vector = case["query_vector"]
    context_weight = case["context_weight"]
    n = len(sentence_vectors)
    if n == 0:
        context_vec = [0.0] * len(query_vector)
    else:
        dim = len(query_vector)
        context_vec = [sum(v[i] for v in sentence_vectors) / n for i in range(dim)]
    def cosine_sim(a, b):
        dot = sum(x*y for x,y in zip(a,b))
        norm_a = math.sqrt(sum(x*x for x in a))
        norm_b = math.sqrt(sum(y*y for y in b))
        if norm_a == 0 or norm_b == 0:
            return 0.0
        return dot / (norm_a * norm_b)
    scores = []
    for vec in sentence_vectors:
        sim_q = cosine_sim(vec, query_vector)
        sim_c = cosine_sim(vec, context_vec)
        combined = (1 - context_weight) * sim_q + context_weight * sim_c
        scores.append(combined)
    indices = list(range(n))
    indices.sort(key=lambda i: (-scores[i], i))
    ranking = [0] * n
    for rank, idx in enumerate(indices, start=1):
        ranking[idx] = rank
    return {"ranking": ranking, "scores": scores}"
}
